import{_ as e,o as s,c as i,a8 as t}from"./chunks/framework.DpsX1MbM.js";const g=JSON.parse('{"title":"EAGLE3 for Llama 3.1 8B: online training","description":"","frontmatter":{},"headers":[],"relativePath":"examples/llama3-eagle3-online.md","filePath":"sections/examples/llama3-eagle3-online.md","lastUpdated":1788846900000}'),n={name:"examples/llama3-eagle3-online.md"};function r(l,a,o,h,p,d){return s(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="eagle3-for-llama-3-1-8b-online-training" tabindex="-1">EAGLE3 for Llama 3.1 8B: online training <a class="header-anchor" href="#eagle3-for-llama-3-1-8b-online-training" aria-label="Permalink to &quot;EAGLE3 for Llama 3.1 8B: online training&quot;">​</a></h1><p>Online training captures the target model&#39;s hidden states while the draft model is training. This walkthrough uses ShareGPT for a small example; a broader, target-regenerated dataset is recommended for production checkpoints.</p><h2 id="_1-prepare-sharegpt" tabindex="-1">1. Prepare ShareGPT <a class="header-anchor" href="#_1-prepare-sharegpt" aria-label="Permalink to &quot;1. Prepare ShareGPT&quot;">​</a></h2><p>Run from the repository root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./scripts/prepare_data.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dataset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sharegpt</span></span></code></pre></div><h2 id="_2-use-the-checked-in-run-config" tabindex="-1">2. Use the checked-in run config <a class="header-anchor" href="#_2-use-the-checked-in-run-config" aria-label="Permalink to &quot;2. Use the checked-in run config&quot;">​</a></h2><p>The canonical recipe is <a href="https://github.com/sgl-project/SpecForge/blob/main/examples/configs/online/disaggregated/external/llama3.1-8b-eagle3-online.yaml" target="_blank" rel="noreferrer"><code>examples/configs/online/disaggregated/external/llama3.1-8b-eagle3-online.yaml</code></a>. It already points at the ShareGPT output from step 1 and records the target, draft architecture, SGLang backend, optimizer settings, and output directory in the same typed contract used by every other training method. Edit that file or use dotted command-line overrides when model and data paths differ; do not create a second copy of the recipe in documentation.</p><h2 id="_3-train" tabindex="-1">3. Train <a class="header-anchor" href="#_3-train" aria-label="Permalink to &quot;3. Train&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">specforge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> train</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/configs/online/disaggregated/external/llama3.1-8b-eagle3-online.yaml</span></span></code></pre></div><p>The recipe points at an external SGLang capture server and starts the disaggregated producer/consumer roles. Configure target TP on the SGLang server; <code>deployment.trainer</code> controls only consumer data parallelism. See <a href="./../basic_usage/training.html#parallel-topologies">Parallel topologies</a>. For a short smoke run, append a small <code>training.max_steps</code> dotted override.</p><h2 id="_4-export-and-benchmark" tabindex="-1">4. Export and benchmark <a class="header-anchor" href="#_4-export-and-benchmark" aria-label="Permalink to &quot;4. Export and benchmark&quot;">​</a></h2><p>Llama 3.1 8B training and benchmarking should use the same system prompt. A reference draft checkpoint is available at <a href="https://huggingface.co/zhuyksir/EAGLE3-Llama-3.1-8B-Instruct" target="_blank" rel="noreferrer">zhuyksir/EAGLE3-Llama-3.1-8B-Instruct</a>.</p><p>The runtime checkpoint contains training state but is not directly loadable by the SGLang speculative decoder. Online resume is consumer-only and reuses the retained transport state; export the final checkpoint before serving:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">specforge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --to</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sglang</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --checkpoint</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./outputs/llama3.1-8b-eagle3-online/llama3.1-8b-eagle3-online-latest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --draft-config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> configs/llama3-8B-eagle3.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --output-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./exports/llama3.1-8b-eagle3-sglang</span></span></code></pre></div>`,14)])])}const k=e(n,[["render",r]]);export{g as __pageData,k as default};
